#!/bin/bash
fail=0
t=$(mktemp); e=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
run() { out=$(BOOKINGS=$t bash src/list.sh "$@" 2>"$e"); rc=$?; err=$(cat "$e"); }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
run --room aoi 2026-01-01; [ "$rc" = 0 ] && [ "$out" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
run --room aoi 2026-01-02; [ "$rc" = 0 ] && [ -z "$out" ] || { echo "list --room with date, no match"; fail=1; }
run --room; [ "$rc" = 2 ] && [ -z "$out" ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
run 2026/11/10; [ "$rc" = 2 ] && [ -z "$out" ] && [ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date slashes"; fail=1; }
run 2026-13-01; [ "$rc" = 2 ] && [ -z "$out" ] && [ "$err" = 'bad date: 2026-13-01 (expected YYYY-MM-DD)' ] || { echo "list bad month"; fail=1; }
run 2026-01-32; [ "$rc" = 2 ] && [ -z "$out" ] && [ "$err" = 'bad date: 2026-01-32 (expected YYYY-MM-DD)' ] || { echo "list bad day"; fail=1; }
run --room aoi 2026/11/10; [ "$rc" = 2 ] && [ -z "$out" ] && [ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list --room with bad date"; fail=1; }
rm -f "$t" "$e"; exit $fail

