cat > src/list.sh <<'EOF'
#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
usage() { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
bad_date() { echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then room=${2:-}; [ -n "$room" ] || usage; shift 2; fi
[ $# -le 1 ] || usage
d=${1:-}
if [ -n "$d" ]; then
  case "$d" in [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) ;; *) bad_date "$d" ;; esac
  m=$((10#${d:5:2})); day=$((10#${d:8:2}))
  { [ "$m" -ge 1 ] && [ "$m" -le 12 ] && [ "$day" -ge 1 ] && [ "$day" -le 31 ]; } || bad_date "$d"
fi
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$d" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
EOF
cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" ] || { echo "list --room with date should not match other day"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); c=$?
[ $c = 2 ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
rm -f "$t"; exit $fail
EOF
cat > spec/list.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
err=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1 >/dev/null); c=$?
[ $c = 2 ] && [ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026-13-01 2>/dev/null); c=$?
[ $c = 2 ] && [ -z "$out" ] || { echo "list month 13 should exit 2 with no stdout"; fail=1; }
rm -f "$t"; exit $fail
EOF
sed -i 's|`bash src/list.sh \[日付\]` で一覧を出す|`bash src/list.sh [--room <部屋>] [日付]` で一覧を出す（`--room` は部屋名の完全一致で絞る）|' README.md
bash tools/check; echo "check exit=$?"; bash tools/lint; echo "lint exit=$?"; cat README.md

