#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
usage() { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
valid_date() {
  case $1 in [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) ;; *) return 1 ;; esac
  local m=$((10#${1:5:2})) d=$((10#${1:8:2}))
  [ "$m" -ge 1 ] && [ "$m" -le 12 ] && [ "$d" -ge 1 ] && [ "$d" -le 31 ]
}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then [ $# -ge 2 ] || usage; room=$2; shift 2; fi
if [ -n "${1:-}" ]; then valid_date "$1" || { echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; }; fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

