#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
usage() { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
[ $# -le 3 ] || usage
room=
if [ "${1:-}" = --room ]; then
  [ -n "${2:-}" ] || usage
  room=$2; shift 2
fi
d=${1:-}
if [ -n "$d" ]; then
  case "$d" in [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]) ;; *) echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2 ;; esac
  m=$((10#${d:5:2})); dy=$((10#${d:8:2}))
  [ "$m" -ge 1 ] && [ "$m" -le 12 ] && [ "$dy" -ge 1 ] && [ "$dy" -le 31 ] || { echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2; }
fi
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$d" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t12:00\t13:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 12:00-13:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-01)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list --room kaede with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" ] || { echo "list --room with other date matched"; fail=1; }
BOOKINGS=$t bash src/list.sh --room > /dev/null 2>"$t.err"; [ $? = 2 ] && grep -qx 'usage: list.sh \[--room ROOM\] \[DATE\]' "$t.err" || { echo "list --room without value"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026/11/10 > /dev/null 2>"$t.err"; [ $? = 2 ] && grep -qx 'bad date: 2026/11/10 (expected YYYY-MM-DD)' "$t.err" || { echo "list bad date"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-13-01 > /dev/null 2>"$t.err"; [ $? = 2 ] || { echo "list month 13 accepted"; fail=1; }
rm -f "$t" "$t.err"; exit $fail

