[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
for d in 2026/11/10 2026-13-01 2026-01-32 2026-1-5; do
  err=$(BOOKINGS=$t bash src/list.sh "$d" 2>&1 >/dev/null); rc=$?
  [ $rc = 2 ] && [ "$err" = "bad date: $d (expected YYYY-MM-DD)" ] || { echo "list bad date $d"; fail=1; }
  [ -z "$(BOOKINGS=$t bash src/list.sh "$d" 2>/dev/null)" ] || { echo "list bad date $d printed to stdout"; fail=1; }
done
rm -f "$t"; exit $fail

