#!/bin/bash
fail=0
t=$(mktemp); e=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t13:00\t14:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 13:00-14:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-02)" ] || { echo "list --room with date, other room"; fail=1; }
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>"$e"; rc=$?
[ "$rc" = 2 ] && grep -qx 'usage: list.sh \[--room ROOM\] \[DATE\]' "$e" || { echo "list --room without value"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null)" ] || { echo "list --room without value wrote stdout"; fail=1; }
rm -f "$t" "$e"; exit $fail

